<template><div class="panel"><div class="tabs"><button :class="{active:tab==='data'}" @click="tab='data'">编辑内容</button><button :class="{active:tab==='style'}" @click="tab='style'">样式设置</button></div><template v-if="tab==='style'"><el-form label-width="96px" label-position="left"><common-title-options/><common-options/></el-form></template><div v-else class="editor"><label class="field"><span>模块标题</span><el-input v-model="modelItem.data.title"/></label><article v-for="(item,i) in modelItem.data.LIST" :key="i"><header><strong>工作经历 {{i+1}}</strong><button :disabled="modelItem.data.LIST.length===1" @click="remove(i)">删除</button></header><div class="grid"><label class="field"><span>公司名称</span><el-input v-model="item.companyName"/></label><label class="field"><span>职位名称</span><el-input v-model="item.posts"/></label><label class="field"><span>开始时间</span><input v-model="item.date[0]" type="month"/></label><label class="field"><span>结束时间</span><input v-model="item.date[1]" type="month"/></label></div><div class="bullet-head"><b>工作成果</b><button @click="addBullet(i)">＋ 添加一条</button></div><div v-for="(content,j) in item.jobContent" :key="j" class="bullet"><span>•</span><el-input v-model="content.content" type="textarea" :autosize="{minRows:2,maxRows:5}" placeholder="用行动 + 方法 + 量化结果描述工作成果"/><button :disabled="item.jobContent.length===1" @click="removeBullet(i,j)">×</button></div></article><button class="add" @click="add">＋ 添加工作经历</button></div></div></template>
<script setup lang="ts">import CommonOptions from './CommonOptions.vue';import CommonTitleOptions from './CommonTitleOptions.vue';import useDesignSelectModelItem from '@/hooks/material/useDesignSelectModelItem';defineOptions({name:'WORK_EXPERIENCE_OPTIONS'});const {modelItem}=useDesignSelectModelItem();const tab=ref('data');const remove=(i:number)=>modelItem.data.LIST.splice(i,1);const add=()=>modelItem.data.LIST.push({date:['',''],companyName:'',posts:'',jobContent:[{content:''}]});const addBullet=(i:number)=>modelItem.data.LIST[i].jobContent.push({content:''});const removeBullet=(i:number,j:number)=>modelItem.data.LIST[i].jobContent.splice(j,1);</script>
<style scoped lang="scss">.panel{padding:14px;color:#18334d}.tabs{display:grid;grid-template-columns:1fr 1fr;padding:4px;background:#eef3f5;border-radius:10px;margin-bottom:18px}.tabs button{height:36px;border:0;border-radius:8px;background:transparent;color:#718397}.tabs .active{background:#fff;color:#008e88;font-weight:700;box-shadow:0 1px 4px #1234}.editor{display:flex;flex-direction:column;gap:14px}.field{display:flex;flex-direction:column;gap:7px}.field>span,.bullet-head b{font-size:13px;color:#536a80}.field input{height:40px;border:1px solid #d9e3e8;border-radius:8px;padding:0 10px;font:inherit}article{border:1px solid #dce6ea;border-radius:14px;background:#fff;padding:14px}header,.bullet-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}button{cursor:pointer}header button,.bullet-head button,.bullet>button{border:0;background:transparent;color:#008e88}header button{color:#d14e43}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.bullet-head{margin:18px 0 9px}.bullet{display:grid;grid-template-columns:12px minmax(0,1fr) 24px;gap:7px;align-items:start;margin-top:8px}.bullet>span{color:#00a49d;padding-top:9px}.bullet>button{font-size:20px;padding-top:5px}.add{height:42px;border:1px dashed #82cfc9;border-radius:10px;background:#f2fbfa;color:#008e88;font-weight:700}button:disabled{opacity:.3}</style>
